using System.Diagnostics;
using System.Text;
using Microsoft.VisualBasic.FileIO;

namespace DedupeLight;

public sealed class MainForm : Form
{
    static readonly Color Ink=Color.FromArgb(24,27,34), Muted=Color.FromArgb(100,108,122), Line=Color.FromArgb(229,232,238), Accent=Color.FromArgb(77,92,230), Surface=Color.White, Canvas=Color.FromArgb(246,247,250);
    readonly TextBox pathBox=new(){PlaceholderText="Choose a folder or drive",Dock=DockStyle.Fill,BorderStyle=BorderStyle.FixedSingle};
    readonly TextBox searchBox=new(){PlaceholderText="Filter results",Width=230,BorderStyle=BorderStyle.FixedSingle};
    readonly Button browse=MakeButton("Browse",true),scan=MakeButton("Scan now"),cancel=MakeButton("Cancel",true),selectExtras=MakeButton("Select extras",true),clearSelection=MakeButton("Clear",true),recycle=MakeButton("Recycle",false,true),move=MakeButton("Move",true),copy=MakeButton("Copy",true),open=MakeButton("Open",true),reveal=MakeButton("Show in Explorer",true),export=MakeButton("Export CSV",true);
    readonly ComboBox keepRule=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=142,Height=34};
    readonly NumericUpDown minimumSize=new(){Minimum=0,Maximum=102400,Value=1,Width=82,ThousandsSeparator=true};
    readonly CheckBox hiddenSystem=new(){Text="Include hidden/system",AutoSize=true,ForeColor=Muted,Padding=new Padding(4,6,0,0)};
    readonly DataGridView grid=new(){Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoGenerateColumns=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=true,RowHeadersVisible=false,BorderStyle=BorderStyle.None,BackgroundColor=Surface,GridColor=Line,CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal};
    readonly Label status=new(){Text="Choose a location to begin",AutoSize=true,ForeColor=Muted},summary=new(){Text="No scan yet",AutoSize=true,Font=new Font("Segoe UI Semibold",10.5f),ForeColor=Ink},selectedSummary=new(){Text="",AutoSize=true,ForeColor=Muted,Padding=new Padding(10,7,0,0)};
    readonly ProgressBar progress=new(){Dock=DockStyle.Bottom,Height=3,Style=ProgressBarStyle.Marquee,Visible=false,MarqueeAnimationSpeed=24};
    readonly string appDataPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DedupeLight"); readonly BindingSource source=new();
    string CachePath=>Path.Combine(appDataPath,"hash-cache.json"); string SettingsPath=>Path.Combine(appDataPath,"settings.json");
    List<DuplicateItem> allItems=[]; CancellationTokenSource? cts; int sortColumn=0; bool sortAscending=true;

    public MainForm(){Text="DedupeLight";Width=1180;Height=760;MinimumSize=new Size(840,560);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",9.5f);BackColor=Canvas;ForeColor=Ink;AllowDrop=true;keepRule.Items.AddRange(["Keep oldest","Keep newest","Keep shortest path"]);keepRule.SelectedIndex=0;BuildLayout();ConfigureGrid();WireEvents();LoadPreferences();SetBusy(false);UpdateSummary();}
    static Button MakeButton(string text,bool secondary=false,bool danger=false)=>new(){Text=text,AutoSize=true,Height=34,FlatStyle=FlatStyle.Flat,Cursor=Cursors.Hand,Padding=new Padding(10,0,10,0),Margin=new Padding(4,0,4,0),BackColor=danger?Color.FromArgb(184,47,57):secondary?Color.White:Accent,ForeColor=danger||!secondary?Color.White:Ink,FlatAppearance={BorderColor=danger?Color.FromArgb(184,47,57):secondary?Line:Accent,BorderSize=1}};
    void BuildLayout()
    {
        var header=new Panel{Dock=DockStyle.Top,Height=88,BackColor=Surface,Padding=new Padding(24,15,24,10)};header.Controls.AddRange([new Label{Text="DedupeLight",AutoSize=true,Font=new Font("Segoe UI Semibold",18),ForeColor=Ink,Location=new Point(22,13)},new Label{Text="Find exact copies. Keep what matters. Reclaim space safely.",AutoSize=true,ForeColor=Muted,Location=new Point(25,51)}]);
        var location=new TableLayoutPanel{Dock=DockStyle.Top,Height=106,BackColor=Surface,Padding=new Padding(22,14,22,12),ColumnCount=4,RowCount=2};location.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(var i=0;i<3;i++)location.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));location.Controls.Add(pathBox,0,0);location.Controls.Add(browse,1,0);location.Controls.Add(scan,2,0);location.Controls.Add(cancel,3,0);
        var options=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,Margin=new Padding(0,9,0,0)};options.Controls.Add(new Label{Text="Minimum file size",AutoSize=true,ForeColor=Muted,Padding=new Padding(0,7,4,0)});options.Controls.Add(minimumSize);options.Controls.Add(new Label{Text="MB",AutoSize=true,ForeColor=Muted,Padding=new Padding(0,7,12,0)});options.Controls.Add(hiddenSystem);location.SetColumnSpan(options,4);location.Controls.Add(options,0,1);
        var resultHead=new TableLayoutPanel{Dock=DockStyle.Top,Height=65,BackColor=Canvas,Padding=new Padding(22,15,22,8),ColumnCount=2};resultHead.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));resultHead.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));var labels=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};labels.Controls.Add(summary);labels.Controls.Add(status);resultHead.Controls.Add(labels,0,0);resultHead.Controls.Add(searchBox,1,0);
        var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=59,BackColor=Surface,Padding=new Padding(18,11,18,8)};actions.Controls.AddRange([keepRule,selectExtras,clearSelection,recycle,move,copy,open,reveal,export,selectedSummary]);var host=new Panel{Dock=DockStyle.Fill,BackColor=Surface,Padding=new Padding(20,0,20,0)};host.Controls.Add(grid);
        Controls.Add(host);Controls.Add(actions);Controls.Add(resultHead);Controls.Add(location);Controls.Add(header);Controls.Add(progress);
    }
    void ConfigureGrid(){grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersHeight=42;grid.RowTemplate.Height=38;grid.ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None;grid.ColumnHeadersDefaultCellStyle=new(){BackColor=Color.FromArgb(248,249,251),ForeColor=Muted,Font=new Font("Segoe UI Semibold",9),SelectionBackColor=Color.FromArgb(248,249,251),Padding=new Padding(4)};grid.DefaultCellStyle=new(){BackColor=Surface,ForeColor=Ink,SelectionBackColor=Color.FromArgb(235,238,255),SelectionForeColor=Ink,Padding=new Padding(4),NullValue=""};grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(251,252,253);grid.Columns.Add(new DataGridViewCheckBoxColumn{DataPropertyName=nameof(DuplicateItem.Selected),HeaderText="",Width=42});grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(DuplicateItem.Group),HeaderText="SET",Width=58,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(DuplicateItem.Name),HeaderText="FILE",Width=240,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(DuplicateItem.Folder),HeaderText="LOCATION",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(DuplicateItem.SizeText),HeaderText="SIZE",Width=92,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(DuplicateItem.ModifiedText),HeaderText="MODIFIED",Width=140,ReadOnly=true});grid.DataSource=source;}
    void WireEvents(){browse.Click+=(_,_)=>ChooseFolder();scan.Click+=async(_,_)=>await ScanAsync();cancel.Click+=(_,_)=>cts?.Cancel();selectExtras.Click+=(_,_)=>SelectExtras();clearSelection.Click+=(_,_)=>{allItems.ForEach(x=>x.Selected=false);grid.Refresh();UpdateActions();};recycle.Click+=async(_,_)=>await RecycleAsync();move.Click+=(_,_)=>Transfer(true);copy.Click+=(_,_)=>Transfer(false);open.Click+=(_,_)=>OpenFile();reveal.Click+=(_,_)=>Reveal();export.Click+=(_,_)=>ExportCsv();searchBox.TextChanged+=(_,_)=>ApplyFilter();grid.SelectionChanged+=(_,_)=>UpdateActions();grid.CellValueChanged+=(_,_)=>UpdateActions();grid.CurrentCellDirtyStateChanged+=(_,_)=>{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0)Reveal();};grid.ColumnHeaderMouseClick+=(_,e)=>SortBy(e.ColumnIndex);pathBox.KeyDown+=async(_,e)=>{if(e.KeyCode==Keys.Enter)await ScanAsync();};DragEnter+=(_,e)=>{if(e.Data?.GetDataPresent(DataFormats.FileDrop)==true)e.Effect=DragDropEffects.Copy;};DragDrop+=(_,e)=>AcceptDrop(e);FormClosing+=(_,_)=>SavePreferences();}
    void ChooseFolder(){using var d=new FolderBrowserDialog{Description="Select a folder or drive to scan",ShowNewFolderButton=false};if(d.ShowDialog()==DialogResult.OK)pathBox.Text=d.SelectedPath;}
    async Task ScanAsync(){var root=pathBox.Text.Trim();if(!Directory.Exists(root)){MessageBox.Show("Choose an existing folder or drive.","DedupeLight",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}SetBusy(true);allItems=[];ApplyFilter();cts=new();var reporter=new Progress<string>(s=>status.Text=s);try{var result=await DuplicateScanner.FindAsync(root,CachePath,new ScanOptions((long)minimumSize.Value*1024*1024,hiddenSystem.Checked),reporter,cts.Token);allItems=result.Items;ApplyFilter();var optimization=result.SizeCandidates-result.FullHashes-result.CacheHits;status.Text=$"Scanned {result.FilesSeen:N0} files • {result.FullHashes:N0} full reads • {result.CacheHits:N0} cached • {Math.Max(0,optimization):N0} rejected by sampling"+(result.Skipped>0?$" • {result.Skipped:N0} skipped":"");}catch(OperationCanceledException){status.Text="Scan cancelled";}catch(Exception ex){status.Text="Scan failed";MessageBox.Show(ex.Message,"Could not scan",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{SetBusy(false);cts?.Dispose();cts=null;UpdateSummary();}}
    void ApplyFilter(){var q=searchBox.Text.Trim();IEnumerable<DuplicateItem> shown=string.IsNullOrEmpty(q)?allItems:allItems.Where(x=>x.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||x.Folder.Contains(q,StringComparison.OrdinalIgnoreCase));shown=sortColumn switch{1=>sortAscending?shown.OrderBy(x=>x.Group):shown.OrderByDescending(x=>x.Group),2=>sortAscending?shown.OrderBy(x=>x.Name):shown.OrderByDescending(x=>x.Name),3=>sortAscending?shown.OrderBy(x=>x.Folder):shown.OrderByDescending(x=>x.Folder),4=>sortAscending?shown.OrderBy(x=>x.Size):shown.OrderByDescending(x=>x.Size),5=>sortAscending?shown.OrderBy(x=>x.ModifiedUtc):shown.OrderByDescending(x=>x.ModifiedUtc),_=>shown.OrderBy(x=>x.Group).ThenBy(x=>x.Path)};source.DataSource=shown.ToList();UpdateSummary();UpdateActions();}
    void UpdateSummary(){var groups=allItems.Select(x=>x.Group).Distinct().Count();var reclaim=allItems.GroupBy(x=>x.Hash).Sum(g=>g.First().Size*(g.Count()-1));summary.Text=groups==0?(cts is null?"No duplicates to review":"Scanning…"):$"{groups:N0} duplicate sets  •  {allItems.Count:N0} files  •  {FormatSize(reclaim)} recoverable";}
    void SetBusy(bool busy){pathBox.Enabled=browse.Enabled=scan.Enabled=minimumSize.Enabled=hiddenSystem.Enabled=keepRule.Enabled=!busy;cancel.Visible=cancel.Enabled=busy;progress.Visible=busy;UpdateActions();}
    void UpdateActions(){var available=allItems.Count>0&&cts is null;var marked=allItems.Where(x=>x.Selected).ToList();var chosen=marked.Count>0||grid.SelectedRows.Count>0;selectExtras.Enabled=clearSelection.Enabled=export.Enabled=available;recycle.Enabled=move.Enabled=copy.Enabled=available&&chosen;open.Enabled=reveal.Enabled=available&&grid.SelectedRows.Count==1;selectedSummary.Text=marked.Count==0?"":$"{marked.Count:N0} selected • {FormatSize(marked.Sum(x=>x.Size))}";}
    List<DuplicateItem> Chosen(){grid.EndEdit();var marked=allItems.Where(x=>x.Selected).ToList();return marked.Count>0?marked:grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.DataBoundItem as DuplicateItem).Where(x=>x is not null).Cast<DuplicateItem>().Distinct().ToList();}DuplicateItem? Current()=>grid.SelectedRows.Count==1?grid.SelectedRows[0].DataBoundItem as DuplicateItem:null;
    void SelectExtras(){allItems.ForEach(x=>x.Selected=false);foreach(var group in allItems.GroupBy(x=>x.Hash)){IOrderedEnumerable<DuplicateItem> ordered=keepRule.SelectedIndex switch{1=>group.OrderByDescending(x=>x.ModifiedUtc).ThenBy(x=>x.Path),2=>group.OrderBy(x=>x.Path.Length).ThenBy(x=>x.Path),_=>group.OrderBy(x=>x.ModifiedUtc).ThenBy(x=>x.Path)};foreach(var item in ordered.Skip(1))item.Selected=true;}grid.Refresh();UpdateActions();status.Text=$"Selected extra copies • {keepRule.SelectedItem?.ToString()?.ToLowerInvariant()} in every set";}
    async Task RecycleAsync(){var chosen=Chosen();if(chosen.Count==0)return;if(chosen.GroupBy(x=>x.Hash).Any(g=>allItems.Count(x=>x.Hash==g.Key)==g.Count())){MessageBox.Show("The selection includes every copy from at least one set. Leave one file unselected before recycling.","Keep one copy",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}var bytes=chosen.Sum(x=>x.Size);if(MessageBox.Show($"Move {chosen.Count} file(s) ({FormatSize(bytes)}) to the Recycle Bin?\n\nYou can restore them later.","Confirm recycle",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;var failed=new List<string>();await Task.Run(()=>{foreach(var x in chosen)try{FileSystem.DeleteFile(x.Path,UIOption.OnlyErrorDialogs,RecycleOption.SendToRecycleBin);}catch{failed.Add(x.Path);}});allItems.RemoveAll(x=>chosen.Contains(x)&&!File.Exists(x.Path));RemoveOrphans();ApplyFilter();status.Text=failed.Count==0?$"Recycled {chosen.Count} file(s) • {FormatSize(bytes)} reclaimed":$"Finished • {failed.Count} file(s) could not be recycled";}
    void Transfer(bool moving){var chosen=Chosen();if(chosen.Count==0)return;using var d=new FolderBrowserDialog{Description=moving?"Move selected files to":"Copy selected files to"};if(d.ShowDialog()!=DialogResult.OK)return;var failed=0;foreach(var x in chosen)try{var target=UniquePath(d.SelectedPath,x.Name);if(moving)File.Move(x.Path,target);else File.Copy(x.Path,target);}catch{failed++;}if(moving){allItems.RemoveAll(x=>chosen.Contains(x)&&!File.Exists(x.Path));RemoveOrphans();ApplyFilter();}status.Text=$"{(moving?"Moved":"Copied")} {chosen.Count-failed} file(s)"+(failed>0?$" • {failed} skipped":"");}
    void OpenFile(){var x=Current();if(x is null)return;try{Process.Start(new ProcessStartInfo(x.Path){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open file");}}void Reveal(){var x=Current();if(x is null)return;Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{x.Path}\""){UseShellExecute=true});}
    void ExportCsv(){using var d=new SaveFileDialog{Filter="CSV file (*.csv)|*.csv",FileName="duplicate-files.csv"};if(d.ShowDialog()!=DialogResult.OK)return;var csv=new StringBuilder("Set,File,Folder,Bytes,Modified,SHA256\r\n");foreach(var x in allItems)csv.AppendLine($"{x.Group},{Csv(x.Name)},{Csv(x.Folder)},{x.Size},{x.ModifiedUtc:O},{x.Hash}");File.WriteAllText(d.FileName,csv.ToString(),new UTF8Encoding(true));status.Text=$"Exported {allItems.Count:N0} results";}
    void SortBy(int column){if(column==0)return;if(sortColumn==column)sortAscending=!sortAscending;else{sortColumn=column;sortAscending=true;}foreach(DataGridViewColumn item in grid.Columns)item.HeaderCell.SortGlyphDirection=SortOrder.None;grid.Columns[column].HeaderCell.SortGlyphDirection=sortAscending?SortOrder.Ascending:SortOrder.Descending;ApplyFilter();}
    void AcceptDrop(DragEventArgs e){if(e.Data?.GetData(DataFormats.FileDrop) is not string[] paths||paths.Length==0)return;var path=paths[0];if(File.Exists(path))path=Path.GetDirectoryName(path)??path;if(Directory.Exists(path)){pathBox.Text=path;status.Text="Folder ready • select Scan now";}}
    void LoadPreferences(){var settings=AppSettings.Load(SettingsPath);if(Directory.Exists(settings.LastPath))pathBox.Text=settings.LastPath;minimumSize.Value=Math.Clamp(settings.MinimumMegabytes,minimumSize.Minimum,minimumSize.Maximum);hiddenSystem.Checked=settings.IncludeHiddenSystem;keepRule.SelectedIndex=Math.Clamp(settings.KeepRule,0,keepRule.Items.Count-1);}
    void SavePreferences()=>new AppSettings(pathBox.Text.Trim(),minimumSize.Value,hiddenSystem.Checked,keepRule.SelectedIndex).Save(SettingsPath);
    static string Csv(string value)=>$"\"{value.Replace("\"","\"\"")}\"";static string UniquePath(string folder,string name){var p=Path.Combine(folder,name);if(!File.Exists(p))return p;var stem=Path.GetFileNameWithoutExtension(name);var ext=Path.GetExtension(name);for(var i=2;;i++){p=Path.Combine(folder,$"{stem} ({i}){ext}");if(!File.Exists(p))return p;}}void RemoveOrphans(){allItems=allItems.GroupBy(x=>x.Hash).Where(g=>g.Count()>1).SelectMany(g=>g).ToList();}
    public static string FormatSize(long bytes){string[] units=["B","KB","MB","GB","TB"];double value=bytes;var unit=0;while(value>=1024&&unit<units.Length-1){value/=1024;unit++;}return $"{value:0.##} {units[unit]}";}
}
